import {getDocument,GlobalWorkerOptions} from './vendor/pdf.mjs';
GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';
const $=id=>document.getElementById(id);let doc,page=1,zoom=1,job,version=0;
const file=new URLSearchParams(location.search).get('file');
const valid=/^docs\/(ntu|ntu-appendix|nthu|nycu|ncku|ncu|nchu|ccu|nsysu|ntust|ntut)\.pdf$/.test(file||'');
async function render(){const v=++version;if(job){job.cancel();try{await job.promise}catch{}}$('status').textContent='正在繪製頁面…';$('prev').disabled=page<=1;$('next').disabled=page>=doc.numPages;$('page').value=page;const p=await doc.getPage(page);if(v!==version)return;const raw=p.getViewport({scale:1});const width=Math.min(document.documentElement.clientWidth-16,950)*zoom;const vp=p.getViewport({scale:width/raw.width});const ratio=Math.min(devicePixelRatio||1,2);const c=$('canvas');c.width=Math.floor(vp.width*ratio);c.height=Math.floor(vp.height*ratio);c.style.width=vp.width+'px';c.style.height=vp.height+'px';c.setAttribute('aria-label',`招生簡章第 ${page} 頁`);job=p.render({canvasContext:c.getContext('2d'),viewport:vp,transform:[ratio,0,0,ratio,0,0]});try{await job.promise;if(v!==version)return;$('status').textContent=`第 ${page} 頁，共 ${doc.numPages} 頁`;$('zoom').textContent=zoom===1?'適合寬度':Math.round(zoom*100)+'%';const text=await p.getTextContent();if(v===version)$('text').textContent=text.items.map(x=>x.str).join(' ');}catch(e){if(e.name!=='RenderingCancelledException')$('status').textContent='此頁無法顯示，請使用上方「官方原檔」。';}}
try{if(!valid)throw Error('無效文件');doc=await getDocument({url:file,cMapUrl:'./vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'./vendor/standard_fonts/',wasmUrl:'./vendor/wasm/'}).promise;$('total').textContent=doc.numPages;$('page').max=doc.numPages;for(const id of ['page','minus','plus'])$(id).disabled=false;await render();}catch{$('status').textContent='簡章暫時無法載入，請使用上方「官方原檔」或「展開閱讀」。';}
$('prev').onclick=()=>{if(page>1){page--;render()}};$('next').onclick=()=>{if(page<doc.numPages){page++;render()}};$('page').onchange=()=>{page=Math.max(1,Math.min(doc.numPages,Math.trunc(Number($('page').value)||1)));render()};$('minus').onclick=()=>{zoom=Math.max(.5,zoom-.25);render()};$('plus').onclick=()=>{zoom=Math.min(2.5,zoom+.25);render()};let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>doc&&render(),150)});
